// And groups predicates with the AND operator between them.
func And(predicates ...predicate.TenantSubscription) predicate.TenantSubscription {
	return predicate.TenantSubscription(sql.AndPredicates(predicates...))
}

// Or groups predicates with the OR operator between them.
func Or(predicates ...predicate.TenantSubscription) predicate.TenantSubscription {
	return predicate.TenantSubscription(sql.OrPredicates(predicates...))
}

// Not applies the not operator on the given predicate.
func Not(p predicate.TenantSubscription) predicate.TenantSubscription {
	return predicate.TenantSubscription(sql.NotPredicates(p))
}
